/**
 *
 * MenuPositioner is a component that positions the menu popup relative to the anchor element.
 *
 * [Live Demo](https://www.primereact.org/menu/)
 *
 * @module MenuPositioner
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { UsePositionerProps } from '@primereact/types/headless/positioner';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { MenuRootInstance } from './MenuRoot.types';
/**
 * Defines passthrough(pt) options type in MenuPositioner component.
 */
export type MenuPositionerPassThroughType<E> = PassThroughType<MenuPositionerInstance, E>;
/**
 * Defines passthrough(pt) options of MenuPositioner component.
 */
export interface MenuPositionerPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: MenuPositionerPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
}
/**
 * Defines valid properties in MenuPositioner component.
 */
export interface MenuPositionerProps extends BaseComponentProps<MenuPositionerInstance, UsePositionerProps, MenuPositionerPassThrough> {
}
/**
 * Defines valid state in MenuPositioner component.
 */
export interface MenuPositionerState {
}
/**
 * Defines the methods and properties exposed by MenuPositioner component.
 */
export interface MenuPositionerExposes {
    /**
     * The Menu component instance.
     */
    menu: MenuRootInstance | undefined | null;
}
/**
 * Instance of MenuPositioner component.
 */
export type MenuPositionerInstance = ComponentInstance<MenuPositionerProps, MenuPositionerState, MenuPositionerExposes>;
